+    assert_eq!(status, StatusCode::OK);
+    let events = parse_sse_data(&body);
+    let chunk = |i: usize| serde_json::from_str::<Value>(&events[i]).unwrap();
+    assert_eq!(chunk(0)["choices"][0]["text"], "o");
+    assert_eq!(chunk(1)["choices"][0]["text"], "k");
